10	// ---- ListAuthorizations 回归测试夹具 ----
11	//
12	// 同一份本地存储中并存：
13	//   - 两名合成患者（pidA、pidB）授权给同一接收方 rcv；
14	//   - 患者 pidA 还同时授权给另一接收方 rcvB；
15	//   - 患者 pidA → rcv 名下覆盖四种授权状态：生效中（整类）、尚未开始
16	//     （限定记录）、已经到期（整类）、已经撤回（整类与限定并存的混合范围）；
17	//   - 患者 pidC 只有档案、从未有过授权。
18	type listAuthFixture struct {
19		s   *Store
20		clk *fakeClock
21	
22		pidA ID
23		pidB ID
24		pidC ID // 有档案但没有任何授权
25		eA1  ID // 患者甲就诊一
26		eA2  ID // 患者甲就诊二
27		eB1  ID // 患者乙就诊
28	
29		recA1 ID // eA1 下已生效诊断
30		recA2 ID // eA1 下已生效诊断
31		recAO ID // eA1 下已生效医嘱
32		recAe ID // eA2 下已生效诊断
33		recB1 ID // eB1 下已生效诊断
34	
35		active   Authorization // 患者甲 → rcv：已开始未到期，整类 eA1 诊断
36		future   Authorization // 患者甲 → rcv：尚未开始，限定 recA1
37		expired  Authorization // 患者甲 → rcv：已经到期，整类 eA2 诊断
38		revoked  Authorization // 患者甲 → rcv：已撤回，整类 eA1 医嘱 + 限定 recA2
39		otherRcv Authorization // 患者甲 → rcvB：生效中，限定 recAO
40		grantB   Authorization // 患者乙 → rcv：生效中，限定 recB1
41	}
42	
43	func setupListAuthFixture(t *testing.T) listAuthFixture {
44		t.Helper()
45		s, clk := newTestStore(t)
46	
47		addPatient := func(name string) ID {
48			t.Helper()
49			p, err := s.RegisterPatient(doc, name)
50			if err != nil {
51				t.Fatalf("register %s: %v", name, err)
52			}
53			return p.ID
54		}
55		addEncounter := func(pid ID) ID {
56			t.Helper()
57			e, err := s.AddEncounter(doc, pid, time.Time{})
58			if err != nil {
59				t.Fatalf("add encounter: %v", err)
60			}
61			return e.ID
62		}
63		effRecord := func(pid, eid ID, category, content string) ID {
64			t.Helper()
65			r, err := s.CreateDraft(doc, pid, eid, category, content)
66			if err != nil {
67				t.Fatalf("create draft: %v", err)
68			}
69			if _, err := s.ActivateRecord(doc, r.ID); err != nil {
70				t.Fatalf("activate: %v", err)
71			}
72			return r.ID
73		}
74	
75		pidA := addPatient("列表回归患者甲")
76		pidB := addPatient("列表回归患者乙")
77		pidC := addPatient("列表回归患者丙")
78		eA1 := addEncounter(pidA)
79		eA2 := addEncounter(pidA)
80		eB1 := addEncounter(pidB)
81	
82		recA1 := effRecord(pidA, eA1, Diagnosis, "甲一诊诊断1")
83		recA2 := effRecord(pidA, eA1, Diagnosis, "甲一诊诊断2")
84		recAO := effRecord(pidA, eA1, Order, "甲一诊医嘱1")
85		recAe := effRecord(pidA, eA2, Diagnosis, "甲二诊诊断1")
86		recB1 := effRecord(pidB, eB1, Diagnosis, "乙一诊诊断1")
87	
88		now := clk.t
89		activeWindow := func() (time.Time, time.Time) { return now.Add(-time.Hour), now.Add(24 * time.Hour) }
90		st, en := activeWindow()
91	
92		active, err := s.Grant(doc, pidA, rcv.ID,
93			[]Scope{{EncounterID: eA1, Category: Diagnosis}}, st, en)
94		if err != nil {
95			t.Fatalf("active grant: %v", err)
96		}
97		future, err := s.GrantSelective(doc, pidA, rcv.ID, nil,
98			[]RecordSelection{sel(eA1, Diagnosis, recA1)},
99			now.Add(24*time.Hour), now.Add(48*time.Hour))
100		if err != nil {
101			t.Fatalf("future grant: %v", err)
102		}
103		expired, err := s.Grant(doc, pidA, rcv.ID,
104			[]Scope{{EncounterID: eA2, Category: Diagnosis}},
105			now.Add(-48*time.Hour), now.Add(-24*time.Hour))
106		if err != nil {
107			t.Fatalf("expired grant: %v", err)
108		}
109		revoked, err := s.GrantSelective(doc, pidA, rcv.ID,
110			[]Scope{{EncounterID: eA1, Category: Order}},
111			[]RecordSelection{sel(eA1, Diagnosis, recA2)}, st, en)
112		if err != nil {
113			t.Fatalf("mixed grant: %v", err)
114		}
115		if err := s.Revoke(doc, pidA, revoked.ID); err != nil {
116			t.Fatalf("revoke: %v", err)
117		}
118		otherRcv, err := s.GrantSelective(doc, pidA, rcvB.ID, nil,
119			[]RecordSelection{sel(eA1, Order, recAO)}, st, en)
120		if err != nil {
121			t.Fatalf("other receiver grant: %v", err)
122		}
123		grantB, err := s.GrantSelective(doc, pidB, rcv.ID, nil,
124			[]RecordSelection{sel(eB1, Diagnosis, recB1)}, st, en)
125		if err != nil {
126			t.Fatalf("patient B grant: %v", err)
127		}
128	
129		return listAuthFixture{
130			s: s, clk: clk,
131			pidA: pidA, pidB: pidB, pidC: pidC,
132			eA1: eA1, eA2: eA2, eB1: eB1,
133			recA1: recA1, recA2: recA2, recAO: recAO, recAe: recAe, recB1: recB1,
134			active: active, future: future, expired: expired, revoked: revoked,
135			otherRcv: otherRcv, grantB: grantB,
136		}
137	}
