224	// ---- 读取时刻：等待结束、开始核对权限的同一时刻 ----
225	
226	// readWhileStoreBusy 模拟读取请求发出后被同一存储上的其他操作阻塞：
227	// 先占用存储互斥锁，再在阻塞期间把时钟推进到 advanceTo，随后放行读取。
228	// 返回读取最终的结果与错误。
229	func readWhileStoreBusy(s *Store, clk *fakeClock, advanceTo time.Time, pid, eid ID, category string) (ReadResult, error) {
230		s.mu.Lock()
231		type outcome struct {
232			res ReadResult
233			err error
234		}
235		done := make(chan outcome, 1)
236		go func() {
237			res, err := s.Read(rcv, pid, eid, category)
238			done <- outcome{res, err}
239		}()
240		// 给读取 goroutine 留出进入 Read 并阻塞在锁上的时间，确保请求
241		// 是在时钟推进之前发出的。
242		time.Sleep(50 * time.Millisecond)
243		clk.t = advanceTo
244		s.mu.Unlock()
245		o := <-done
246		return o.res, o.err
247	}
