250		s, clk := newTestStore(t)
251		pid, eid := setupPatientEncounter(t, s)
252		rec, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "x")
253		if _, err := s.ActivateRecord(doc, rec.ID); err != nil {
254			t.Fatal(err)
255		}
256	
257		start := clk.t.Add(-time.Hour)
258		end := clk.t.Add(time.Hour)
259		if _, err := s.Grant(doc, pid, rcv.ID, []Scope{{EncounterID: eid, Category: Diagnosis}}, start, end); err != nil {
260			t.Fatal(err)
261		}
262	
263		// 发出请求时授权尚未到期，但等待期间到达截止时刻：核对权限时授权
264		// 已失效，必须拒绝，且结果不携带记录标识、数量或内容。
265		res, err := readWhileStoreBusy(s, clk, end, pid, eid, Diagnosis)
266		if !errors.Is(err, ErrAccessDenied) {
267			t.Fatalf("grant expired during wait: err = %v, want ErrAccessDenied", err)
268		}
269		if res.EncounterID != "" || res.Category != "" || len(res.Records) != 0 {
270			t.Fatalf("denied read must not carry record info: %+v", res)
271		}
272	
273		// 反向：发出请求时第二个授权尚未开始，等待期间进入其时间窗且未到期：
274		// 应按核对时刻允许读取。
275		start2 := end.Add(30 * time.Minute)
276		end2 := start2.Add(2 * time.Hour)
277		if _, err := s.Grant(doc, pid, rcv.ID, []Scope{{EncounterID: eid, Category: Diagnosis}}, start2, end2); err != nil {
278			t.Fatal(err)
279		}
280		clk.t = end // 请求发出时刻：授权一已到期，授权二尚未开始
281		res, err = readWhileStoreBusy(s, clk, start2.Add(time.Minute), pid, eid, Diagnosis)
282		if err != nil {
283			t.Fatalf("grant started during wait must allow read: %v", err)
284		}
285		if len(res.Records) != 1 || res.Records[0].RecordID != rec.ID {
286			t.Fatalf("read after wait = %+v, want the one effective record", res)
287		}
288	}
