290	func TestReadWaitExpiryFallsBackToStillValidSelectiveGrant(t *testing.T) {
291		s, clk := newTestStore(t)
292		pid, eid := setupPatientEncounter(t, s)
293		mkDiag := func(content string) ID {
294			t.Helper()
295			r, err := s.CreateDraft(doc, pid, eid, Diagnosis, content)
296			if err != nil {
297				t.Fatal(err)
298			}
299			if _, err := s.ActivateRecord(doc, r.ID); err != nil {
300				t.Fatal(err)
301			}
302			return r.ID
303		}
304		r1 := mkDiag("诊断1")
305		r2 := mkDiag("诊断2")
306	
307		start := clk.t.Add(-time.Hour)
308		end := clk.t.Add(time.Hour)
309		// 整类授权在等待期间到期；限定授权只选中 r2，且在核对时刻仍有效。
310		if _, err := s.Grant(doc, pid, rcv.ID, []Scope{{EncounterID: eid, Category: Diagnosis}}, start, end); err != nil {
311			t.Fatal(err)
312		}
313		if _, err := s.GrantSelective(doc, pid, rcv.ID, nil,
314			[]RecordSelection{{EncounterID: eid, Category: Diagnosis, RecordID: r2}},
315			start, end.Add(2*time.Hour)); err != nil {
316			t.Fatal(err)
317		}
318	
319		// 发出请求时整类授权仍有效；核对权限时它已到期：只返回仍有效的
320		// 限定授权明确选中的 r2，已到期的整类授权不能带出 r1，也不能因此
321		// 拒绝全部读取。
322		res, err := readWhileStoreBusy(s, clk, end, pid, eid, Diagnosis)
323		if err != nil {
324			t.Fatalf("selective grant still valid: %v", err)
325		}
326		if len(res.Records) != 1 || res.Records[0].RecordID != r2 {
327			t.Fatalf("read = %+v, want only the selected record %q", res.Records, r2)
328		}
329		if res.Records[0].RecordID == r1 {
330			t.Fatal("expired whole-category grant leaked an unselected record")
331		}
332	}
