336	func TestMultipleGrantsSameReceiverJudgedIndependently(t *testing.T) {
337		s, clk := newTestStore(t)
338		pid, eid := setupPatientEncounter(t, s)
339		rec, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "x")
340		if _, err := s.ActivateRecord(doc, rec.ID); err != nil {
