392	// ---- 交换：每条记录必须被绑定的那一条授权自身覆盖 ----
393	
394	func TestCreateExchangeBoundToSelectiveAuthorization(t *testing.T) {
395		f := setupSelective(t)
396	
397		// 绑定授权只选定 r1。
398		bound, err := f.s.GrantSelective(doc, f.pid, rcv.ID, nil,
399			[]RecordSelection{sel(f.e1, Diagnosis, f.r1)}, f.start, f.end)
400		if err != nil {
401			t.Fatal(err)
402		}
403		// 同一接收方的另一条整类授权覆盖整个 e1 诊断（含 r2），但不能补足绑定授权。
404		if _, err := f.s.Grant(doc, f.pid, rcv.ID,
405			[]Scope{{EncounterID: f.e1, Category: Diagnosis}}, f.start, f.end); err != nil {
406			t.Fatal(err)
