409		// 选中记录打包成功并固化创建时版本。
410		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID, []ID{f.r1}, "req-sel-1")
411		if err != nil {
412			t.Fatalf("create with selected record: %v", err)
413		}
414		if len(x.Package.Records) != 1 || x.Package.Records[0].VersionID != f.r1v1.ID {
415			t.Fatalf("package wrong: %+v", x.Package.Records)
416		}
