428			t.Fatalf("retry refroze package: %+v", retry.Package.Records)
429		}
430		_ = v2
431	
432		// 夹带一条只有其他授权覆盖的 r2：整包拒绝，不留交换或审计，也不占用请求号。
433		auditBefore := len(mustAudit(t, f.s, f.pid))
434		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, bound.ID,
435			[]ID{f.r1, f.r2}, "req-sel-2"); !errors.Is(err, ErrAccessDenied) {
