			sel(f.e1, Diagnosis, f.r1), // 与上一条重叠
			sel(f.e1, Diagnosis, f.r2),
		}, f.start, f.end); err != nil {
		t.Fatal(err)
	}
	res, _ := f.s.Read(rcv, f.pid, f.e1, Diagnosis)
