449			t.Fatal(err)
450		}
451		if g2.Status != ExchangeRejected || g2.Receipt == nil ||
452			g2.Receipt.Outcome != ReceiptRejected || g2.Receipt.Reason != "接收方核对后真实拒绝" {
453			t.Fatalf("genuine receipt not stored: %+v", g2)
454		}
