523	
524	// ---- 待回执交换：在手中结果里补造假回执，重新查询仍没有回执 ----
525	
526	func TestFabricatedReceiptOnPendingExchangeDoesNotPersist(t *testing.T) {
527		f := setupExchange(t)
528		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
529			[]ID{f.diag, f.ord}, "req-iso-noreceipt")
530		if err != nil {
531			t.Fatal(err)
532		}
533	
534		g, err := f.s.GetExchange(doc, f.pid, x.ID)
535		if err != nil {
536			t.Fatal(err)
537		}
538		if g.Status != ExchangePending || g.Receipt != nil {
539			t.Fatalf("new exchange should have no receipt: %+v", g)
540		}
541	
