	}
	if d.Status != ExchangePending {
		t.Fatalf("delivery status = %q, want %q", d.Status, ExchangePending)
	}

	// 自始至终没有任何回执审计。
	if c := receiptAuditCount(t, f.s, f.pid); c != 0 {
		t.Fatalf("receipt audits = %d, want 0", c)
	}
