9	
10	// 本文件为接收方 Read 查阅入口补“同一接收方同时持有多名患者有效授权”时的
11	// 患者隔离回归保障：每次读取只能使用所请求患者自己的授权，不能因为接收方
12	// 相同、记录类别相同，或另一名患者拥有更宽的整类范围，就让本次读取多出内容。
13	//
14	// 覆盖的约定：
15	//   - 同一份本地存储中两名合成患者各自有就诊、已生效诊断与未生效草稿；同一
16	//     接收方对甲只有选定诊断的限定授权，对乙有诊断整类授权，两份授权同时
17	//     有效。读甲的就诊只能看到明确选中的诊断（同类未选中者、授权后新增者、
18	//     草稿都不出现）；读乙的就诊能看到乙在该次就诊中的全部已生效诊断
19	//     （含授权后才生效者），草稿不出现；两边都不混入对方的记录；
20	//   - 返回的版本标识、版本号、正文与生效时间准确对应获准记录的当前生效
21	//     版本：已更正记录不退回旧版，也不带出更正原因；
22	//   - 患者与就诊必须属于同一份档案：甲的患者标识配乙的就诊标识（以及反向
23	//     混用）都返回 ErrAccessDenied 与全空结果，不返回内部查询使用的
24	//     ErrMismatchedPatient，也不能借另一份有效授权把混用请求当作合法读取；
25	//   - 格式合法但不存在的患者或就诊标识同样返回 ErrAccessDenied 与全空结果，
26	//     接收方无法通过错误种类或附带资料区分“不存在”与“无权访问”；
27	//   - 正常读取与被拒绝的读取都是只读的：不新增审计、不改授权、不生成记录
28	//     版本；之后用原本正确的患者与就诊组合再读，获准内容保持原样。
29	
30	// countVersions 统计库内记录版本总数，用于核对读取不产生新版本。
31	func countVersions(s *Store) int {
32		c := 0
33		_ = s.view(func(snap *snapshot) error { c = len(snap.Versions); return nil })
34		return c
35	}
36	
37	// assertReadDeniedBlank 核对一次被拒绝的查阅：错误是且仅是 ErrAccessDenied
38	// （不能是内部查询使用的 ErrMismatchedPatient，也不能是泄露存在性的
39	// ErrNotFound），返回结果全空——不携带就诊、类别、记录标识、数量或正文。
40	func assertReadDeniedBlank(t *testing.T, err error, res ReadResult, label string) {
41		t.Helper()
42		if !errors.Is(err, ErrAccessDenied) {
43			t.Fatalf("%s: err = %v, want ErrAccessDenied", label, err)
44		}
45		if errors.Is(err, ErrMismatchedPatient) {
46			t.Fatalf("%s: err = %v, must not surface internal cross-patient error", label, err)
47		}
48		if errors.Is(err, ErrNotFound) {
49			t.Fatalf("%s: err = %v, must not reveal existence", label, err)
50		}
51		if !reflect.DeepEqual(res, ReadResult{}) {
52			t.Fatalf("%s: denied read must carry no encounter/category/record data, got %+v", label, res)
53		}
54	}
55	
56	// assertEffectiveRecord 核对一条查阅结果准确对应某条记录的当前生效版本：
57	// 记录标识、版本标识、版本号、正文与生效时间逐项一致。
58	func assertEffectiveRecord(t *testing.T, got EffectiveRecord, recordID ID, want Version, label string) {
59		t.Helper()
60		if got.RecordID != recordID {
61			t.Fatalf("%s: record id = %q, want %q", label, got.RecordID, recordID)
62		}
63		if got.VersionID != want.ID {
64			t.Fatalf("%s: version id = %q, want current effective %q", label, got.VersionID, want.ID)
65		}
66		if got.Version != want.Number {
67			t.Fatalf("%s: version = %d, want %d", label, got.Version, want.Number)
68		}
69		if got.Content != want.Content {
70			t.Fatalf("%s: content = %q, want %q", label, got.Content, want.Content)
71		}
72		if !got.EffectiveAt.Equal(want.CreatedAt) {
73			t.Fatalf("%s: effective at = %v, want %v", label, got.EffectiveAt, want.CreatedAt)
74		}
75	}
76	
77	func TestReadIsolatesPatientsSharingOneReceiver(t *testing.T) {
78		s, clk := newTestStore(t)
79		t0 := clk.t // 2026-01-01 09:00 UTC
80	
81		// 同一份本地存储中的两名合成患者，各有一次就诊。
82		pa, err := s.RegisterPatient(doc, "合成患者甲")
83		if err != nil {
84			t.Fatal(err)
85		}
86		pb, err := s.RegisterPatient(doc2, "合成患者乙")
87		if err != nil {
88			t.Fatal(err)
89		}
90		a1, err := s.AddEncounter(doc, pa.ID, t0)
91		if err != nil {
92			t.Fatal(err)
93		}
94		b1, err := s.AddEncounter(doc2, pb.ID, t0)
95		if err != nil {
96			t.Fatal(err)
97		}
98	
99		// 每条诊断的标识、正文与版本信息都逐条可区分归属；更正原因同样专有，
100		// 便于发现旧版回退、原因外泄与跨患者串台。
101		const (
102			aSelV1Text = "甲-选中诊断 v1：上呼吸道感染"
103			aSelV2Text = "甲-选中诊断 v2：急性鼻咽炎（更正后）"
104			aSelReason = "甲-选中诊断的更正原因"
105			aOtherText = "甲-未选中诊断：过敏性鼻炎"
106			aDraftText = "甲-未生效草稿：头晕待查"
107			aLateText  = "甲-授权后新增诊断：急性咽炎"
108			bOneV1Text = "乙-诊断一 v1：高血压"
109			bOneV2Text = "乙-诊断一 v2：高血压 2 级（更正后）"
110			bOneReason = "乙-诊断一的更正原因"
111			bTwoText   = "乙-诊断二：2 型糖尿病"
112			bDraftText = "乙-未生效草稿：失眠待查"
113			bLateText  = "乙-授权后新增诊断：高脂血症"
114		)
115	
116		// 甲：两条将生效的诊断（一条将被选中、一条同类但不选中）+ 一条永不生效的草稿。
117		aSel := mustCreateDraft(t, s, pa.ID, a1.ID, Diagnosis, aSelV1Text)
118		aOther := mustCreateDraft(t, s, pa.ID, a1.ID, Diagnosis, aOtherText)
119		aDraft := mustCreateDraft(t, s, pa.ID, a1.ID, Diagnosis, aDraftText)
120		// 乙：两条将生效的诊断 + 一条永不生效的草稿。
121		bOne := mustCreateDraft(t, s, pb.ID, b1.ID, Diagnosis, bOneV1Text)
122		bTwo := mustCreateDraft(t, s, pb.ID, b1.ID, Diagnosis, bTwoText)
123		bDraft := mustCreateDraft(t, s, pb.ID, b1.ID, Diagnosis, bDraftText)
124	
125		clk.t = t0.Add(time.Hour) // t1：第一批生效
126		aSelV1 := activateAs(t, s, doc, aSel)
127		aOtherV := activateAs(t, s, doc, aOther)
128		bTwoV := activateAs(t, s, doc2, bTwo)
129	
130		clk.t = clk.t.Add(time.Hour) // t2：第二批生效
131		bOneV1 := activateAs(t, s, doc2, bOne)
132	
133		clk.t = clk.t.Add(time.Hour) // t3：两名患者各有一条诊断被更正到 v2
134		aSelV2 := correctAs(t, s, doc, aSel, 1, aSelV2Text, aSelReason)
135		bOneV2 := correctAs(t, s, doc2, bOne, 1, bOneV2Text, bOneReason)
136	
137		clk.t = clk.t.Add(time.Hour) // t4：两份授权同时建立、同时有效
138		grantStart := clk.t.Add(-time.Hour)
139		grantEnd := clk.t.Add(48 * time.Hour)
140		// 甲：只选中 aSel 的限定授权（同类其他记录不在范围内）。
141		grantA, err := s.GrantSelective(doc, pa.ID, rcv.ID, nil,
142			[]RecordSelection{sel(a1.ID, Diagnosis, aSel)}, grantStart, grantEnd)
143		if err != nil {
144			t.Fatalf("selective grant for A: %v", err)
145		}
146		// 乙：诊断整类授权（该就诊下全部已生效诊断，含授权后才生效者）。
147		grantB := grantAs(t, s, doc2, pb.ID, rcv.ID,
148			[]Scope{{EncounterID: b1.ID, Category: Diagnosis}}, grantStart, grantEnd)
149	
150		clk.t = clk.t.Add(time.Hour) // t5：授权建立后两名患者各新增一条生效诊断
151		aLate := mustCreateDraft(t, s, pa.ID, a1.ID, Diagnosis, aLateText)
152		aLateV := activateAs(t, s, doc, aLate)
153		bLate := mustCreateDraft(t, s, pb.ID, b1.ID, Diagnosis, bLateText)
154		bLateV := activateAs(t, s, doc2, bLate)
155	
156		clk.t = clk.t.Add(time.Hour) // t6：查阅时刻，两份授权都在有效期内
157	
158		// 读取前的只读基线：审计、授权、记录与版本总量。
159		auditsABefore := mustAudit(t, s, pa.ID)
160		auditsBBefore := mustAudit(t, s, pb.ID)
161		authsABefore, err := s.ListAuthorizations(doc, pa.ID, "")
162		if err != nil {
163			t.Fatal(err)
164		}
165		authsBBefore, err := s.ListAuthorizations(doc2, pb.ID, "")
166		if err != nil {
167			t.Fatal(err)
168		}
169		versionsBefore := countVersions(s)
170		recordsBefore := countRecords(s)
171	
172		// ---- 读甲：只能看到明确选中的诊断，且取更正后的当前生效版本 ----
173	
174		resA, err := s.Read(rcv, pa.ID, a1.ID, Diagnosis)
175		if err != nil {
176			t.Fatalf("read A: %v", err)
177		}
178		if resA.EncounterID != a1.ID || resA.Category != Diagnosis {
179			t.Fatalf("read A echo wrong: %+v", resA)
180		}
181		if len(resA.Records) != 1 {
182			t.Fatalf("read A records = %d (%v), want exactly the selected diagnosis",
183				len(resA.Records), readRecordIDs(resA))
184		}
185		selRec := resA.Records[0]
186		// 已更正的选中记录：必须是 v2，不能退回 v1，也不能带出更正原因。
187		assertEffectiveRecord(t, selRec, aSel, aSelV2, "read A selected diagnosis")
188		if selRec.VersionID == aSelV1.ID || selRec.Content == aSelV1Text {
189			t.Fatalf("read A reverted to the pre-correction version: %+v", selRec)
190		}
191		if selRec.Content == aSelReason {
192			t.Fatalf("read A leaked the correction reason as content: %+v", selRec)
193		}
194		// 同类但未选中的记录、授权后新增的记录、草稿都不能因限定授权之外的理由出现。
195		for _, leaked := range []ID{aOther, aLate, aDraft} {
196			if readRecordIDs(resA)[leaked] {
197				t.Fatalf("read A must not contain unselected/draft record %q: %+v", leaked, resA.Records)
198			}
199		}
200		// 乙的整类授权更宽，但甲的读取不能因此多出乙的任何记录或正文。
201		for _, er := range resA.Records {
202			if er.RecordID == bOne || er.RecordID == bTwo || er.RecordID == bLate || er.RecordID == bDraft {
203				t.Fatalf("patient B record %q leaked into read A", er.RecordID)
204			}
205			if er.Content == bOneV1Text || er.Content == bOneV2Text || er.Content == bTwoText ||
206				er.Content == bLateText || er.Content == bDraftText {
207				t.Fatalf("patient B content leaked into read A: %q", er.Content)
208			}
209		}
210	
211		// ---- 读乙：整类授权覆盖该次就诊中的全部已生效诊断（含授权后生效者） ----
212	
213		resB, err := s.Read(rcv, pb.ID, b1.ID, Diagnosis)
214		if err != nil {
215			t.Fatalf("read B: %v", err)
216		}
217		if resB.EncounterID != b1.ID || resB.Category != Diagnosis {
218			t.Fatalf("read B echo wrong: %+v", resB)
219		}
220		wantB := map[ID]Version{bOne: bOneV2, bTwo: bTwoV, bLate: bLateV}
221		if len(resB.Records) != len(wantB) {
222			t.Fatalf("read B records = %d (%v), want all %d effective diagnoses of encounter B1",
223				len(resB.Records), readRecordIDs(resB), len(wantB))
224		}
225		for i := 1; i < len(resB.Records); i++ {
226			if resB.Records[i-1].RecordID > resB.Records[i].RecordID {
227				t.Fatalf("read B not in stable record-id order: %+v", resB.Records)
228			}
229		}
230		for _, er := range resB.Records {
231			want, ok := wantB[er.RecordID]
232			if !ok {
233				t.Fatalf("read B contains unexpected record %q (%q)", er.RecordID, er.Content)
234			}
235			assertEffectiveRecord(t, er, er.RecordID, want, "read B record "+er.RecordID)
236		}
237		// 乙的已更正诊断同样取当前版本 v2，不退回 v1、不带出更正原因。
238		oneRec := resB.Records[0]
239		for _, er := range resB.Records {
240			if er.RecordID == bOne {
241				oneRec = er
242			}
243		}
244		if oneRec.VersionID == bOneV1.ID || oneRec.Content == bOneV1Text {
245			t.Fatalf("read B reverted to the pre-correction version: %+v", oneRec)
246		}
247		if oneRec.Content == bOneReason {
248			t.Fatalf("read B leaked the correction reason as content: %+v", oneRec)
249		}
250		// 乙的草稿与甲的任何记录都不能混入。
251		for _, leaked := range []ID{bDraft, aSel, aOther, aLate, aDraft} {
252			if readRecordIDs(resB)[leaked] {
253				t.Fatalf("read B must not contain draft/foreign record %q: %+v", leaked, resB.Records)
254			}
255		}
256		for _, er := range resB.Records {
257			if er.Content == aSelV1Text || er.Content == aSelV2Text || er.Content == aOtherText ||
258				er.Content == aLateText || er.Content == aDraftText {
259				t.Fatalf("patient A content leaked into read B: %q", er.Content)
260			}
261		}
262	
263		// ---- 跨患者混用：患者标识与就诊标识必须属于同一份档案 ----
264		//
265		// 接收方对甲、乙分别持有有效授权，但两种混用都不能借另一份授权变成
266		// 合法读取：统一返回 ErrAccessDenied 与全空结果，且不能返回内部查询
267		// 使用的跨患者错误。
268	
269		mixAB, err := s.Read(rcv, pa.ID, b1.ID, Diagnosis)
270		assertReadDeniedBlank(t, err, mixAB, "patient A id + patient B encounter")
271		mixBA, err := s.Read(rcv, pb.ID, a1.ID, Diagnosis)
272		assertReadDeniedBlank(t, err, mixBA, "patient B id + patient A encounter")
273	
274		// ---- 格式合法但不存在的标识：与无权访问不可区分 ----
275	
276		ghostPat := ID("pat_000000000000000000000000")
277		ghostEnc := ID("enc_000000000000000000000000")
278		deniedGhostPat, err := s.Read(rcv, ghostPat, a1.ID, Diagnosis)
279		assertReadDeniedBlank(t, err, deniedGhostPat, "nonexistent patient")
280		deniedGhostEnc, err := s.Read(rcv, pa.ID, ghostEnc, Diagnosis)
281		assertReadDeniedBlank(t, err, deniedGhostEnc, "nonexistent encounter")
282		deniedGhostBoth, err := s.Read(rcv, ghostPat, ghostEnc, Diagnosis)
283		assertReadDeniedBlank(t, err, deniedGhostBoth, "nonexistent patient and encounter")
284		// 不存在的标识与跨患者混用给出的错误种类完全一致，接收方无法据此分辨。
285		if _, mixErr := s.Read(rcv, pa.ID, b1.ID, Diagnosis); !errors.Is(mixErr, ErrAccessDenied) ||
286			errors.Is(mixErr, ErrNotFound) || errors.Is(mixErr, ErrMismatchedPatient) {
287			t.Fatalf("cross-patient mix must be indistinguishable from nonexistent ids, err = %v", mixErr)
288		}
289	
290		// ---- 正常读取与被拒绝的读取都是只读的：不新增审计、不改授权、不生成版本 ----
291	
292		assertAuditMatches(t, mustAudit(t, s, pa.ID), auditsABefore, "patient A audits after reads")
293		assertAuditMatches(t, mustAudit(t, s, pb.ID), auditsBBefore, "patient B audits after reads")
294		authsAAfter, err := s.ListAuthorizations(doc, pa.ID, "")
295		if err != nil {
296			t.Fatal(err)
297		}
298		if !reflect.DeepEqual(authsAAfter, authsABefore) {
299			t.Fatalf("patient A authorizations changed as a result of reads:\n before=%+v\n after =%+v",
300				authsABefore, authsAAfter)
301		}
302		authsBAfter, err := s.ListAuthorizations(doc2, pb.ID, "")
303		if err != nil {
304			t.Fatal(err)
305		}
306		if !reflect.DeepEqual(authsBAfter, authsBBefore) {
307			t.Fatalf("patient B authorizations changed as a result of reads:\n before=%+v\n after =%+v",
308				authsBBefore, authsBAfter)
309		}
310		if got := countVersions(s); got != versionsBefore {
311			t.Fatalf("reads generated record versions: before=%d after=%d", versionsBefore, got)
312		}
313		if got := countRecords(s); got != recordsBefore {
314			t.Fatalf("reads changed record count: before=%d after=%d", recordsBefore, got)
315		}
316	
317		// ---- 之后用原本正确的患者与就诊组合再读：获准内容保持原样 ----
318	
319		againA, err := s.Read(rcv, pa.ID, a1.ID, Diagnosis)
320		if err != nil {
321			t.Fatalf("re-read A: %v", err)
322		}
323		if !reflect.DeepEqual(againA, resA) {
324			t.Fatalf("read A changed after denied/mixed attempts:\n first=%+v\n again=%+v", resA, againA)
325		}
326		againB, err := s.Read(rcv, pb.ID, b1.ID, Diagnosis)
327		if err != nil {
328			t.Fatalf("re-read B: %v", err)
329		}
330		if !reflect.DeepEqual(againB, resB) {
331			t.Fatalf("read B changed after denied/mixed attempts:\n first=%+v\n again=%+v", resB, againB)
332		}
333	
334		// 防止 unused（授权标识是上面授权未变化断言的对象来源）。
335		_ = grantA
336		_ = grantB
337		_ = aOtherV
338		_ = aLateV
339		_ = bLateV
340	}
341

