1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“按患者查看审计历史”的返回结果隔离约定补回归保障：
10	// 内部使用者通过 AuditEvents 或 Chart 拿到审计列表后，可以在自己的程序里
11	// 整理这些结果；这种本地整理不能成为修改正式审计历史的另一条入口。
12	//
13	// 覆盖的约定：
14	//   - 调用方改写返回事件的操作人、动作、对象、所属患者或时间，替换、调换、
15	//     删除列表元素后，再次查询仍得到原来的事件标识、内容、数量与追加次序；
16	//   - 较早取得的另一份结果保持原样（同一入口多份，以及 AuditEvents 与
17	//     Chart 两个入口之间都一样）；
18	//   - 事件时间相同时仍保留真实操作的先后关系；
19	//   - 本地改动不产生审计事件；随后的合法更正在正式历史末尾追加真实事件，
20	//     不继承被改过的本地值，旧查询结果仍停留在查询当时；
21	//   - 停用后内部使用者仍可查看历史且隔离要求不变；持有效内容授权的接收方
22	//     读取审计列表一律 ErrAccessDenied，且不携带审计身份或对象信息。
23	//
24	// 预期基线由测试自行拷贝（刻意不调用生产代码的任何拷贝逻辑）：即便生产侧
25	// 退化为返回内部切片或指针，基线仍保持查询时内容，隔离断言才能真正抓住泄漏。
26	
27	// ---- 测试自用的独立拷贝与比对（不经过生产代码） ----
28	
29	// snapshotAudit 独立拷贝整份审计列表作为预期基线。AuditEvent 为纯值类型，
30	// 逐元素复制即与存储侧完全脱离。
31	func snapshotAudit(evs []AuditEvent) []AuditEvent {
32		out := make([]AuditEvent, len(evs))
33		copy(out, evs)
34		return out
35	}
36	
37	// tamperAuditEvent 在调用方手中的一条返回事件上改写全部可写字段：
38	// 事件标识、所属患者、操作人、动作、对象类别与标识、发生时间。
39	func tamperAuditEvent(ev *AuditEvent) {
40		ev.ID = "aud_local_tampered"
41		ev.PatientID = "pat_local_tampered"
42		ev.ActorID = "actor_local_tampered"
43		ev.Action = "local_forged_action"
44		ev.ObjectType = "local_forged_object"
45		ev.ObjectID = "obj_local_tampered"
46		ev.OccurredAt = time.Date(1999, 12, 31, 23, 59, 59, 0, time.UTC)
47	}
48	
49	// forgedAuditEvent 构造一条完全本地伪造的事件，用于替换列表元素。
50	func forgedAuditEvent() AuditEvent {
51		return AuditEvent{
52			ID:         "aud_local_forged",
53			PatientID:  "pat_local_forged",
54			ActorID:    "actor_local_forged",
55			Action:     "forged_action",
56			ObjectType: "forged_object",
57			ObjectID:   "obj_local_forged",
58			OccurredAt: time.Date(2001, 1, 1, 0, 0, 0, 0, time.UTC),
59		}
60	}
61	
62	func assertAuditMatches(t *testing.T, got, want []AuditEvent, label string) {
63		t.Helper()
64		if len(got) != len(want) {
65			t.Fatalf("%s: event count changed: got %d (%v), want %d (%v)",
66				label, len(got), auditIDList(got), len(want), auditIDList(want))
67		}
68		for i := range want {
69			if got[i] != want[i] {
70				t.Fatalf("%s: event %d changed:\n got=%+v\nwant=%+v", label, i, got[i], want[i])
71			}
72		}
73	}
74	
75	func auditIDList(evs []AuditEvent) []ID {
76		ids := make([]ID, len(evs))
77		for i, ev := range evs {
78			ids[i] = ev.ID
79		}
80		return ids
81	}
82	
83	// scrambleAuditResult 在调用方手中的一份结果上做尽可能广泛的本地整理：
84	// 逐事件改写全部字段、用伪造事件替换一个元素、首尾调换、删除末尾元素。
85	func scrambleAuditResult(evs []AuditEvent) []AuditEvent {
86		for i := range evs {
87			tamperAuditEvent(&evs[i])
88		}
89		if len(evs) >= 2 {
90			evs[1] = forgedAuditEvent()
91			evs[0], evs[len(evs)-1] = evs[len(evs)-1], evs[0]
92		}
93		return evs[:len(evs)-1]
94	}
95	
96	// ---- 形态：多次生效/更正/授权/撤回留下可区分的事件；时间相同也保持追加次序 ----
97	
98	func TestAuditEventsShapeAndAppendOrder(t *testing.T) {
99		s, clk := newTestStore(t)
100		pid, eid := setupPatientEncounter(t, s)
101	
102		// 两名内部使用者交替操作，动作、对象、时间交错，足以区分每条事件。
103		recA := mustCreateDraft(t, s, pid, eid, Diagnosis, "诊断第 1 版内容")
104		recB := mustCreateDraft(t, s, pid, eid, Order, "医嘱第 1 版内容")
105	
106		t0 := clk.t
107		if _, err := s.ActivateRecord(doc, recA); err != nil {
108			t.Fatal(err)
109		}
110		// 与上一事件同一时刻：时间相同也必须保留真实操作的先后关系。
111		if _, err := s.ActivateRecord(doc2, recB); err != nil {
112			t.Fatal(err)
113		}
114		clk.t = clk.t.Add(time.Hour)
115		t1 := clk.t
116		if _, err := s.CorrectRecord(doc2, recA, 1, "诊断第 2 版内容", "诊断更正原因"); err != nil {
117			t.Fatal(err)
118		}
119		if _, err := s.CorrectRecord(doc, recB, 1, "医嘱第 2 版内容", "医嘱更正原因"); err != nil {
120			t.Fatal(err)
121		}
122		clk.t = clk.t.Add(time.Hour)
123		t2 := clk.t
124		auth, err := s.Grant(doc, pid, rcv.ID,
125			[]Scope{{EncounterID: eid, Category: Diagnosis}},
126			clk.t.Add(-time.Hour), clk.t.Add(time.Hour))
127		if err != nil {
128			t.Fatal(err)
129		}
130		clk.t = clk.t.Add(time.Hour)
131		t3 := clk.t
132		if err := s.Revoke(doc2, pid, auth.ID); err != nil {
133			t.Fatal(err)
134		}
135	
136		events := mustAudit(t, s, pid)
137		want := []struct {
138			action, objectType, objectID, actorID string
139			at                                    time.Time
140		}{
141			{ActionActivated, "record", recA, doc.ID, t0},
142			{ActionActivated, "record", recB, doc2.ID, t0},
143			{ActionCorrected, "record", recA, doc2.ID, t1},
144			{ActionCorrected, "record", recB, doc.ID, t1},
145			{ActionGranted, "authorization", auth.ID, doc.ID, t2},
146			{ActionRevoked, "authorization", auth.ID, doc2.ID, t3},
147		}
148		if len(events) != len(want) {
149			t.Fatalf("event count = %d (%v), want %d", len(events), auditIDList(events), len(want))
150		}
151		seenIDs := map[ID]bool{}
152		for i, w := range want {
153			ev := events[i]
154			if ev.Action != w.action || ev.ObjectType != w.objectType || ev.ObjectID != w.objectID ||
155				ev.ActorID != w.actorID || ev.PatientID != pid {
156				t.Fatalf("event %d = %+v, want action %s on %s by %s", i, ev, w.action, w.objectID, w.actorID)
157			}
158			if !ev.OccurredAt.Equal(w.at) {
159				t.Fatalf("event %d time = %v, want %v", i, ev.OccurredAt, w.at)
160			}
161			if ev.ID == "" || seenIDs[ev.ID] {
162				t.Fatalf("event %d id missing or duplicated: %q", i, ev.ID)
163			}
164			seenIDs[ev.ID] = true
165		}
166		// 时间相同的两对事件必须按真实操作顺序相邻出现（上面已按位置断言，
167		// 这里再显式确认它们的时间戳确实相同，保证该场景被覆盖）。
168		if !events[0].OccurredAt.Equal(events[1].OccurredAt) || !events[2].OccurredAt.Equal(events[3].OccurredAt) {
169			t.Fatal("test setup should produce same-timestamp event pairs")
170		}
171	
172		// Chart 入口看到同一份历史。
173		chart, err := s.Chart(doc, pid)
174		if err != nil {
175			t.Fatal(err)
176		}
177		assertAuditMatches(t, chart.AuditEvents, events, "chart audit view")
178	}
179	
180	// ---- 隔离：本地整理改不到正式历史，也改不到另一份结果（两个入口都适用） ----
181	
182	func TestAuditEventsResultIsDetachedFromStore(t *testing.T) {
183		s, clk := newTestStore(t)
184		pid, eid := setupPatientEncounter(t, s)
185	
186		recA := mustCreateDraft(t, s, pid, eid, Diagnosis, "诊断第 1 版内容")
187		recB := mustCreateDraft(t, s, pid, eid, Order, "医嘱第 1 版内容")
188		mustActivate(t, s, recA)
189		if _, err := s.ActivateRecord(doc2, recB); err != nil {
190			t.Fatal(err)
191		}
192		clk.t = clk.t.Add(time.Hour)
193		mustCorrect(t, s, recA, 1, "诊断第 2 版内容", "诊断更正原因")
194		if _, err := s.CorrectRecord(doc2, recB, 1, "医嘱第 2 版内容", "医嘱更正原因"); err != nil {
195			t.Fatal(err)
196		}
197	
198		// 同一入口取得两份结果；另一入口取得一份。基线独立拷贝。
199		first := mustAudit(t, s, pid)
200		second := mustAudit(t, s, pid)
201		chartBefore, err := s.Chart(doc, pid)
202		if err != nil {
203			t.Fatal(err)
204		}
205		viaChart := chartBefore.AuditEvents
206		want := snapshotAudit(first)
207		if len(want) != 4 {
208			t.Fatalf("setup should produce 4 events, got %d", len(want))
209		}
210	
211		// 在第一份结果上广泛本地整理：改写字段、替换元素、调换、删除。
212		first = scrambleAuditResult(first)
213	
214		// 同一入口再次查询：正式历史保持原标识、内容、数量与追加次序。
215		again := mustAudit(t, s, pid)
216		assertAuditMatches(t, again, want, "AuditEvents re-query after local tampering")
217	
218		// 同一入口较早取得的另一份结果保持原样。
219		assertAuditMatches(t, second, want, "earlier AuditEvents result after local tampering")
220	
221		// 另一入口较早取得的结果保持原样；重新查询同样不受影响。
222		assertAuditMatches(t, viaChart, want, "earlier Chart result after local tampering")
223		chartAfter, err := s.Chart(doc, pid)
224		if err != nil {
225			t.Fatal(err)
226		}
227		assertAuditMatches(t, chartAfter.AuditEvents, want, "Chart re-query after local tampering")
228	
229		// 反过来也成立：篡改从 Chart 取得的结果，AuditEvents 入口不受波及。
230		tamperedChart := mustAudit(t, s, pid) // 先记录当前正式历史
231		chartView, err := s.Chart(doc, pid)
232		if err != nil {
233			t.Fatal(err)
234		}
235		scrambleAuditResult(chartView.AuditEvents)
236		assertAuditMatches(t, mustAudit(t, s, pid), tamperedChart, "AuditEvents after tampering a Chart result")
237	
238		// 本地整理既不是查询也不是写操作：不能增加、更换或删除正式审计事件。
239		assertAuditMatches(t, mustAudit(t, s, pid), want, "official audit history unchanged by local edits")
240	}
241	
242	// ---- 合法更正：正式历史末尾追加真实事件；旧结果停留在查询当时 ----
243	
244	func TestAuditCorrectionAppendsRealEventAfterLocalTampering(t *testing.T) {
245		s, clk := newTestStore(t)
246		pid, eid := setupPatientEncounter(t, s)
247		rid := mustCreateDraft(t, s, pid, eid, Diagnosis, "诊断第 1 版内容")
248		mustActivate(t, s, rid)
249		clk.t = clk.t.Add(time.Hour)
250		mustCorrect(t, s, rid, 1, "诊断第 2 版内容", "第一次更正原因")
251	
252		// 更正前取得、此后不在本地改动的结果：应一直代表查询当时的历史。
253		frozen := mustAudit(t, s, pid)
254		if len(frozen) != 2 {
255			t.Fatalf("setup should produce 2 events, got %d", len(frozen))
256		}
257	
258		// 另一份结果被调用方任意改写（操作人、对象、患者、时间全部换成本地值）。
259		local := mustAudit(t, s, pid)
260		tamperAuditEvent(&local[0])
261	
262		// 通过正常入口完成一次合法更正。
263		clk.t = clk.t.Add(time.Hour)
264		correctionTime := clk.t
265		v3, err := s.CorrectRecord(doc2, rid, 2, "诊断第 3 版内容", "第二次更正原因")
266		if err != nil {
267			t.Fatalf("legitimate correction: %v", err)
268		}
269	
270		// 正式历史：此前事件原样保留，末尾追加本次更正的真实事件。
271		after := mustAudit(t, s, pid)
272		if len(after) != 3 {
273			t.Fatalf("correction should append exactly one event, got %d (%v)", len(after), auditIDList(after))
274		}
275		if after[0] != frozen[0] || after[1] != frozen[1] {
276			t.Fatalf("prior official history changed:\n got=%+v\nwant=%+v", after[:2], frozen)
277		}
278		ev := after[2]
279		if ev.Action != ActionCorrected || ev.ObjectType != "record" || ev.ObjectID != rid {
280			t.Fatalf("new event must point at the actual record: %+v", ev)
281		}
282		if ev.ActorID != doc2.ID || ev.PatientID != pid {
283			t.Fatalf("new event must name the actual actor and patient: %+v", ev)
284		}
285		if !ev.OccurredAt.Equal(correctionTime) {
286			t.Fatalf("new event time = %v, want the real operation time %v", ev.OccurredAt, correctionTime)
287		}
288		if ev.ID == "" || ev.ID == frozen[0].ID || ev.ID == frozen[1].ID {
289			t.Fatalf("new event id missing or reused: %q", ev.ID)
290		}
291		// 新事件的任何字段都不能继承被改过的本地值。
292		forged := local[0]
293		if ev.ID == forged.ID || ev.ActorID == forged.ActorID || ev.Action == forged.Action ||
294			ev.ObjectType == forged.ObjectType || ev.ObjectID == forged.ObjectID ||
295			ev.PatientID == forged.PatientID || ev.OccurredAt.Equal(forged.OccurredAt) {
296			t.Fatalf("new event inherited tampered local values:\n got=%+v\nlocal=%+v", ev, forged)
297		}
298		_ = v3
299	
300		// 原来的查询结果仍代表查询当时的历史，不会自动多出新事件。
301		if len(frozen) != 2 {
302			t.Fatalf("earlier result gained the new event: %d", len(frozen))
303		}
304		// 被本地改过的那份结果保持调用方留下的样子，不被正式状态回写。
305		if local[0].ActorID != "actor_local_tampered" || local[0].ObjectID != "obj_local_tampered" {
306			t.Fatalf("locally edited result changed unexpectedly: %+v", local[0])
307		}
308	}
309	
310	// ---- 停用后：内部查看与隔离要求不变；接收方持有效授权也不得读取审计列表 ----
311	
312	func TestAuditIsolationAfterDeactivation(t *testing.T) {
313		s, clk := newTestStore(t)
314		pid, eid := setupPatientEncounter(t, s)
315		rid := mustCreateDraft(t, s, pid, eid, Diagnosis, "诊断第 1 版内容")
316		mustActivate(t, s, rid)
317		mustCorrect(t, s, rid, 1, "诊断第 2 版内容", "更正原因")
318	
319		// 接收方持有覆盖该患者内容的有效授权（停用不撤回授权）。
320		if _, err := s.Grant(doc, pid, rcv.ID,
321			[]Scope{{EncounterID: eid, Category: Diagnosis}},
322			clk.t.Add(-time.Hour), clk.t.Add(time.Hour)); err != nil {
323			t.Fatalf("grant: %v", err)
324		}
325		if err := s.DeactivatePatient(doc, pid); err != nil {
326			t.Fatalf("deactivate: %v", err)
327		}
328	
329		// 停用后内部使用者仍可按现有权限查看完整历史。
330		baseline := mustAudit(t, s, pid)
331		if got := auditActions(baseline); got[ActionActivated] != 1 || got[ActionCorrected] != 1 ||
332			got[ActionGranted] != 1 || got[ActionDeactivated] != 1 {
333			t.Fatalf("deactivated chart history incomplete: %v", got)
334		}
335		want := snapshotAudit(baseline)
336	
337		// 隔离要求继续成立：本地整理改不到正式历史，也改不到另一份结果。
338		first := mustAudit(t, s, pid)
339		second := mustAudit(t, s, pid)
340		scrambleAuditResult(first)
341		assertAuditMatches(t, mustAudit(t, s, pid), want, "AuditEvents after tampering (deactivated)")
342		assertAuditMatches(t, second, want, "earlier result after tampering (deactivated)")
343		chart, err := s.Chart(doc, pid)
344		if err != nil {
345			t.Fatal(err)
346		}
347		assertAuditMatches(t, chart.AuditEvents, want, "Chart audit view (deactivated)")
348	
349		// 接收方即使持有该患者的有效内容授权，也不能读取审计列表：
350		// 返回 ErrAccessDenied，且不携带审计身份或对象信息。
351		evs, err := s.AuditEvents(rcv, pid)
352		if !errors.Is(err, ErrAccessDenied) {
353			t.Fatalf("receiver AuditEvents err = %v, want ErrAccessDenied", err)
354		}
355		if evs != nil {
356			t.Fatalf("denied audit query must carry no events, got %+v", evs)
357		}
358		ch, err := s.Chart(rcv, pid)
359		if !errors.Is(err, ErrAccessDenied) {
360			t.Fatalf("receiver Chart err = %v, want ErrAccessDenied", err)
361		}
362		if ch.Patient != (Patient{}) || ch.Encounters != nil || ch.Records != nil || ch.AuditEvents != nil {
363			t.Fatalf("denied chart query must carry no audit identity or object info, got %+v", ch)
364		}
365	}
